import os import requests
base_url = os.environ["BPM_BASE_URL"].rstrip("/") schema_channel = os.environ.get("BPM_SCHEMA_CHANNEL", "release-153") session = requests.Session()
ready = session.get(f"{base_url}/health/ready", timeout=10) ready.raise_for_status() assert ready.json() == {"status": "ready", "ready": True}
payload = {"document": {"policies": {"DisableTelemetry": True, "BlockAboutConfig": True}}} validation = session.post(f"{base_url}/api/validate/{schema_channel}", json=payload, timeout=10) validation.raise_for_status() assert validation.json() == {"ok": True, "profile": schema_channel}
created = session.post( f"{base_url}/api/profiles", json={"name": "docs-python-example", "schema_version": schema_channel, "flags": payload["document"]["policies"]}, timeout=10, ) created.raise_for_status() profile = created.json() assert profile["schema_version"] == schema_channel
exported = session.get( f"{base_url}/api/export/profiles/{profile['id']}/firefox/policies.json?pretty=1", timeout=10, ) exported.raise_for_status() assert exported.json() == {"policies": payload["document"]["policies"]}
